"""Generated by the NL to Flow Diagram Encoder Pipeline."""

class Stack:
    def __init__(self):
        self.data = []

    def push(self, item):
        self.data.append(item)

    def pop(self):
        if (len(self.data) == 0):
            return 'Underflow'
        return self.data.pop(-1)

    def peek(self):
        if (len(self.data) == 0):
            return 'Empty'
        return self.data[(-1)]
